#include <bits/stdc++.h>
using namespace std;

#define F first
#define S second
#define PB push_back
#define sz(s) int((s).size())
#define bit(n,k) (((n)>>(k))&1)

typedef long long ll;
typedef pair<int,int> pii;
typedef pair<ll,ll> pll;
typedef unsigned int ui;

const int Lg=18, Tw=(1<<Lg), Max=Tw+10;

int matrix[Max][Lg+3], buffer[Lg+3], buffer2[Lg+3], factorial[Max], inv_factorial[Max], count_bits, n_value, mod=1e9+7;

int power_mod(int base, int exponent){
    int result=1;
    while(exponent){
        if(exponent&1) result=1ll*result*base%mod;
        base=1ll*base*base%mod;
        exponent>>=1;
    }
    return result;
}

void add_arrays(int *dest,int *src){
    for(int i=0;i<=count_bits;i++)
        dest[i]=(dest[i]+src[i])%mod;
}

void subtract_arrays(int *dest,int *src){
    for(int i=0;i<=count_bits;i++)
        dest[i]=(dest[i]-src[i])%mod;
}

void multiply_convolution(int *res,int *a,int *b){
    memset(buffer,0,sizeof buffer);
    for(int i=0;i<=count_bits;i++){
        for(int j=0;j<=i;j++){
            buffer[i]=(buffer[i]+1ll*a[j]*b[i-j])%mod;
        }
    }
    memcpy(res,buffer,sizeof buffer);
}

void forward_transform(int a[][Lg+3]){
    for(int i=0;i<count_bits;i++)
        for(int msk=n_value;msk>=0;msk--)
            if(bit(msk,i))
                add_arrays(a[msk],a[msk ^ (1<<i)]);
}

void inverse_transform(int a[][Lg+3]){
    for(int i=0;i<count_bits;i++)
        for(int msk=n_value;msk>=0;msk--)
            if(bit(msk,i))
                subtract_arrays(a[msk],a[msk ^ (1<<i)]);
}

vector<int> positions;

int main(){
    int K; cin>>n_value>>K>>mod;
    int total_pow=power_mod(K,n_value);
    if(n_value&1){ cout<<total_pow<<endl; return 0; }
    count_bits=__builtin_popcount(n_value);
    int original_n=n_value;
    for(int i=0;i<Lg;i++){
        if(bit(n_value,i))
            positions.PB(i);
    }
    n_value=(1<<count_bits)-1;
    factorial[0]=1;
    for(int i=1;i<Max;i++)
        factorial[i]=1ll*i*factorial[i-1]%mod;
    inv_factorial[Max-1]=power_mod(factorial[Max-1],mod-2);
    for(int i=Max-2;i>=0;i--)
        inv_factorial[i]=1ll*(i+1)*inv_factorial[i+1]%mod;
    for(int i=0;i<=n_value;i++){
        int val=0;
        for(int j=0;j<count_bits;j++)
            val+=bit(i,j)*(1<<positions[j]);
        matrix[i][__builtin_popcount(i)]=inv_factorial[val];
    }
    forward_transform(matrix);
    for(int i=0;i<=n_value;i++){
        int K_copy=K;
        memset(buffer2,0,sizeof buffer2); buffer2[0]=1;
        while(K_copy){
            if(K_copy&1) multiply_convolution(buffer2,buffer2,matrix[i]);
            multiply_convolution(matrix[i],matrix[i],matrix[i]);
            K_copy>>=1;
        }
        memcpy(matrix[i],buffer2,sizeof buffer2);
    }
    inverse_transform(matrix);
    int result=(total_pow - 1ll*matrix[n_value][count_bits]*factorial[original_n])%mod;
    if(result<0) result+=mod;
    cout<<result<<endl;
    return 0;
}
